const roles = {
  admin: ['*'],
  professional: ['patients:read','patients:write','appointments:read','appointments:write','sessions:read','sessions:write','messages:read','messages:write'],
  reception: ['patients:read','patients:write','appointments:read','appointments:write','messages:read','messages:write','inventory:read','inventory:write'],
  finance: ['patients:read','finance:read','finance:write','inventory:read']
};

const allowed = (user, permission) => roles[user.role]?.includes('*') || roles[user.role]?.includes(permission);
const json = (res, status, payload) => { res.setHeader('cache-control','no-store');res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' }); res.end(JSON.stringify(payload)); };
const routeMatch = (pattern, pathname) => { const keys=[]; const regex=new RegExp(`^${pattern.replace(/:([a-z_]+)/g,(_,key)=>{keys.push(key);return '([^/]+)'})}$`); const match=pathname.match(regex); return match ? Object.fromEntries(keys.map((k,i)=>[k,decodeURIComponent(match[i+1])])) : null; };

async function body(req) {
  const chunks=[]; let size=0;
  for await (const chunk of req) { size += chunk.length; if (size > 1_000_000) throw Object.assign(new Error('Corpo da requisição excede 1 MB'), { status: 413 }); chunks.push(chunk); }
  if (!chunks.length) return {};
  try { return JSON.parse(Buffer.concat(chunks)); } catch { throw Object.assign(new Error('JSON inválido'), { status: 400 }); }
}

